import{f as t,o as i,c as e,ah as l}from"./chunks/framework.5bt9HFMa.js";const m=JSON.parse('{"title":"Golang 学习","description":"从语言基础到工程实践，再到云原生与性能优化的 Go 学习路线。","frontmatter":{"title":"Golang 学习","date":"2026-03-19T00:00:00.000Z","description":"从语言基础到工程实践，再到云原生与性能优化的 Go 学习路线。","tags":["Golang","Go","后端","云原生"],"next":false},"headers":[],"relativePath":"series/golang/index.md","filePath":"series/golang/index.md","lastUpdated":1777791679000}'),a={name:"series/golang/index.md"};function c(o,s,k,d,h,b){return i(),e("div",null,s[0]||(s[0]=[l('<h1 id="go-语言学习" tabindex="-1">Go 语言学习 <a class="header-anchor" href="#go-语言学习" aria-label="Permalink to &quot;Go 语言学习&quot;">​</a></h1><p>这份笔记用来梳理 Go 的完整学习路径，不只追求会写语法，而是从语言设计、并发模型、工程实践到服务落地，逐步建立可用于真实项目的知识体系。</p><p>更详细的学习还是请参见：<a href="https://golang.halfiisland.com/guide.html" target="_blank" rel="noreferrer">Go 语言学习指南</a></p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>理解 Go 的核心语法、类型系统与错误处理方式</li><li>建立对 goroutine、channel、context 的系统认知</li><li>掌握标准库中最常用的网络、I/O、测试与并发工具</li><li>能独立完成一个可部署的后端服务</li><li>具备基础的性能分析、调试与工程化能力</li></ul><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><h3 id="第一阶段-入门与语言基础" tabindex="-1">第一阶段：入门与语言基础 <a class="header-anchor" href="#第一阶段-入门与语言基础" aria-label="Permalink to &quot;第一阶段：入门与语言基础&quot;">​</a></h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> <a href="./1.1扬帆起go.html">Go 开发环境、模块管理与项目结构</a></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <a href="./1.2基本语法.html">基本语法：变量、常量、流程控制、函数</a></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <a href="./1.3数据结构.html">数组、切片、map、字符串的底层特性</a></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <a href="./1.4面向对象.html">struct、method、interface 的设计思想</a></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 指针、值拷贝、引用语义</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 错误处理：<code>error</code>、<code>panic</code>、<code>recover</code></li></ul><h3 id="第二阶段-进阶语法与工程能力" tabindex="-1">第二阶段：进阶语法与工程能力 <a class="header-anchor" href="#第二阶段-进阶语法与工程能力" aria-label="Permalink to &quot;第二阶段：进阶语法与工程能力&quot;">​</a></h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 包管理与模块化组织</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 接口抽象与依赖解耦</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 泛型基础与常见使用场景</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 反射机制及其适用边界</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 常见设计模式在 Go 中的实现方式</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 常见代码规范、lint 与格式化工具</li></ul><h3 id="第三阶段-并发编程" tabindex="-1">第三阶段：并发编程 <a class="header-anchor" href="#第三阶段-并发编程" aria-label="Permalink to &quot;第三阶段：并发编程&quot;">​</a></h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> goroutine 调度模型</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> channel 通信模型与常见模式</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <code>select</code>、超时控制与退出机制</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <code>context</code> 的取消、超时与链路传递</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <code>sync</code> 包：互斥锁、读写锁、WaitGroup、Once、Pool</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 并发安全、竞态条件与死锁排查</li></ul><h3 id="第四阶段-标准库与服务开发" tabindex="-1">第四阶段：标准库与服务开发 <a class="header-anchor" href="#第四阶段-标准库与服务开发" aria-label="Permalink to &quot;第四阶段：标准库与服务开发&quot;">​</a></h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 文件 I/O、缓冲、序列化与反序列化</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 时间处理、日志、配置管理</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <code>net/http</code> 与 HTTP 服务开发</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> JSON API、参数校验与中间件设计</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 数据库访问：<code>database/sql</code>、连接池、事务</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Web 框架选型与实践：Gin</li></ul><h3 id="第五阶段-测试、调试与性能优化" tabindex="-1">第五阶段：测试、调试与性能优化 <a class="header-anchor" href="#第五阶段-测试、调试与性能优化" aria-label="Permalink to &quot;第五阶段：测试、调试与性能优化&quot;">​</a></h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 单元测试、表驱动测试与 benchmark</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> mock、依赖注入与可测试性设计</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> pprof 性能分析</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 内存逃逸、GC 基础与对象分配优化</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 常见性能瓶颈定位方法</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 调试工具与线上问题排查思路</li></ul><h3 id="第六阶段-工程化与云原生" tabindex="-1">第六阶段：工程化与云原生 <a class="header-anchor" href="#第六阶段-工程化与云原生" aria-label="Permalink to &quot;第六阶段：工程化与云原生&quot;">​</a></h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 配置分层、日志规范与错误追踪</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Docker 化部署与多环境管理</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> gRPC 与微服务通信</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 消息队列、缓存与任务系统</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 可观测性：metrics、tracing、logging</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Go 在 Kubernetes / 云原生生态中的角色</li></ul><h3 id="第七阶段-源码与底层机制" tabindex="-1">第七阶段：源码与底层机制 <a class="header-anchor" href="#第七阶段-源码与底层机制" aria-label="Permalink to &quot;第七阶段：源码与底层机制&quot;">​</a></h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> runtime 基础：内存分配、调度器、栈增长</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> channel 与 map 的底层实现</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> interface 内部表示</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> GC 工作机制与优化方向</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 编译流程与常见编译参数</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 标准库源码阅读方法</li></ul>',20)]))}const p=t(a,[["render",c]]);export{m as __pageData,p as default};
